
.panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* 设施网格 */
.facilities-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.facility-card {
  background: var(--al-bg-card);
  border-radius: 12px;
  padding: 12px;
  border: 1px solid var(--al-border);
}

.facility-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
}

.facility-icon {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  flex-shrink: 0;

  &.oil {
    background: rgba(74, 158, 255, 0.2);
    color: var(--al-accent);
  }
  &.material {
    background: rgba(38, 208, 206, 0.2);
    color: var(--al-success);
  }
  &.dock {
    background: rgba(255, 170, 74, 0.2);
    color: var(--al-warn);
  }
  &.research {
    background: rgba(164, 130, 255, 0.2);
    color: #a482ff;
  }
}

.facility-info {
  flex: 1;
}

.facility-name {
  color: var(--al-text-secondary);
  font-size: 12px;
}

.facility-level {
  color: var(--al-text-primary);
  font-size: 14px;
  font-weight: 700;
}

.facility-stat {
  margin-bottom: 6px;
}

.facility-stats-row {
  display: flex;
  gap: 12px;
  margin-bottom: 6px;
}

.mini-stat {
  display: flex;
  align-items: baseline;
  gap: 4px;
}

.stat-value {
  font-size: 18px;
  font-weight: 700;
  color: var(--al-text-primary);
}

.stat-label {
  font-size: 10px;
  color: var(--al-text-muted);
}

.level-bar {
  height: 4px;
  background: rgba(139, 185, 254, 0.15);
  border-radius: 2px;
  overflow: hidden;
}

.level-fill {
  height: 100%;
  border-radius: 2px;
  background: var(--al-accent);
  transition: width 0.4s ease;

  &.material {
    background: var(--al-success);
  }
  &.dock {
    background: var(--al-warn);
  }
  &.research {
    background: #a482ff;
  }
}

/* 科研 */
.section-card {
  background: var(--al-bg-card);
  border-radius: 12px;
  padding: 14px;
  border: 1px solid var(--al-border);
}

.section-title {
  color: var(--al-text-secondary);
  font-size: 14px;
  margin-bottom: 10px;
  display: flex;
  align-items: center;
  gap: 8px;

  i {
    font-size: 14px;
  }
}

.research-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.research-item {
  background: var(--al-bg-item);
  border-radius: 8px;
  padding: 10px 12px;
  cursor: pointer;
  transition: all 0.2s;

  &:hover {
    background: var(--al-bg-hover);
  }
}

.research-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 6px;
}

.research-name {
  color: var(--al-text-secondary);
  font-size: 14px;
  font-weight: 600;
}

.research-type {
  background: rgba(139, 185, 254, 0.15);
  color: var(--al-text-muted);
  padding: 2px 8px;
  border-radius: 10px;
  font-size: 11px;
}

.progress-bar {
  height: 6px;
  background: rgba(139, 185, 254, 0.15);
  border-radius: 3px;
  overflow: hidden;
  margin-bottom: 6px;
}

.progress-fill {
  height: 100%;
  border-radius: 3px;
  background: var(--al-accent-gradient);
  transition: width 0.4s ease;
}

.research-time {
  font-size: 11px;
  color: var(--al-text-muted);
}

.research-detail {
  font-size: 11px;
  color: var(--al-text-muted);
  margin-top: 6px;
  padding-top: 6px;
  border-top: 1px solid var(--al-border);
  line-height: 1.6;
}

.empty-state {
  text-align: center;
  padding: 14px;
  color: var(--al-text-muted);
  font-size: 12px;
}

/* 已研发 */
.completed-section {
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--al-border);
}

.sub-title {
  color: var(--al-text-muted);
  font-size: 12px;
  margin-bottom: 8px;
}

.completed-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.chip {
  background: rgba(38, 208, 206, 0.15);
  color: var(--al-success);
  padding: 4px 10px;
  border-radius: 12px;
  font-size: 12px;
  font-weight: 600;
}

.chip-type {
  font-weight: 400;
  font-size: 10px;
  color: var(--al-text-muted);
  margin-left: 4px;
}

/* 展开动画 */
.slide-enter-active,
.slide-leave-active {
  transition: all 0.2s ease;
  overflow: hidden;
}
.slide-enter-from,
.slide-leave-to {
  opacity: 0;
  max-height: 0;
}
.slide-enter-to,
.slide-leave-from {
  opacity: 1;
  max-height: 60px;
}

@media (max-width: 360px) {
  .facilities-grid {
    grid-template-columns: 1fr;
  }
}
