
.port-container {
  width: 100%;
  max-width: 420px;
  background: #0a1f44;
  border-radius: 16px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  font-family: var(--al-font);
  border: 1px solid rgba(139, 185, 254, 0.15);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
  margin: 0 auto;
}

.content-area {
  flex: 1;
  overflow-y: auto;
  padding: 12px;
  min-height: 0;
  max-height: 520px;
}

/* 页面切换动画 */
.fade-enter-active,
.fade-leave-active {
  transition: all 0.3s ease;
}

.fade-enter-from {
  opacity: 0;
  transform: translateY(8px);
}

.fade-leave-to {
  opacity: 0;
  transform: translateY(-8px);
}
