
.header-bar {
  background: rgba(10, 31, 68, 0.9);
  border-bottom: 1px solid var(--al-border);
}

.top-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 14px 6px;
}

.date-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.main-date {
  font-size: 15px;
  font-weight: 600;
  color: var(--al-text-primary);
}

.sub-info {
  display: flex;
  gap: 6px;
}

.badge {
  font-size: 11px;
  padding: 1px 8px;
  border-radius: 10px;
  color: var(--al-text-muted);
  background: rgba(74, 158, 255, 0.15);
}

.weather-group {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--al-text-secondary);
  font-size: 13px;
}

.weather-icon {
  font-size: 22px;
}

/* 资源摘要 */
.resource-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 6px 14px 10px;
  flex-wrap: wrap;
}

.resource-item {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 12px;
  color: var(--al-text-muted);

  i {
    font-size: 13px;
    color: var(--al-accent);
  }

  &.council i {
    color: var(--al-success);
  }
}

.resource-value {
  font-weight: 700;
  font-size: 14px;
  color: var(--al-text-primary);

  &.danger {
    color: var(--al-danger);
    animation: pulse-text 1.5s infinite;
  }
}

.resource-label {
  font-size: 11px;
}

.alert-indicator {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-left: auto;
  padding: 3px 10px;
  border-radius: 12px;
  background: rgba(255, 74, 74, 0.2);
  color: var(--al-danger);
  font-size: 11px;
  font-weight: 600;
  animation: pulse-bg 1.5s infinite;

  i {
    font-size: 12px;
  }
}

@keyframes pulse-text {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.6;
  }
}

@keyframes pulse-bg {
  0% {
    box-shadow: 0 0 0 0 rgba(255, 74, 74, 0.3);
  }
  70% {
    box-shadow: 0 0 0 6px rgba(255, 74, 74, 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgba(255, 74, 74, 0);
  }
}
