
.panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.resources-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.resource-card {
  background: var(--al-bg-card);
  border-radius: 12px;
  padding: 14px;
  border: 1px solid var(--al-border);
  transition: all 0.3s;

  &.danger {
    border-color: rgba(255, 74, 74, 0.4);
    animation: danger-pulse 2s infinite;
  }
}

@keyframes danger-pulse {
  0%,
  100% {
    box-shadow: 0 0 0 0 rgba(255, 74, 74, 0);
  }
  50% {
    box-shadow: 0 0 12px 2px rgba(255, 74, 74, 0.15);
  }
}

.resource-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
}

.resource-icon {
  width: 30px;
  height: 30px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(74, 158, 255, 0.2);
  color: var(--al-accent);
  font-size: 14px;

  &.material {
    background: rgba(38, 208, 206, 0.2);
    color: var(--al-success);
  }
}

.resource-label {
  color: var(--al-text-secondary);
  font-size: 12px;
}

.resource-amount {
  font-size: 28px;
  font-weight: 700;
  color: var(--al-text-primary);
  margin-bottom: 6px;
}

.resource-sub {
  display: flex;
  flex-direction: column;
  gap: 3px;
  font-size: 11px;
  margin-bottom: 6px;

  .income {
    color: var(--al-success);
  }
  .expense {
    color: var(--al-warn);
  }

  i {
    margin-right: 3px;
    font-size: 10px;
  }
}

.balance-bar {
  padding-top: 6px;
  border-top: 1px solid var(--al-border);
}

.balance-label {
  font-size: 11px;
  color: var(--al-text-muted);

  .positive {
    color: var(--al-success);
    font-weight: 600;
  }
  .negative {
    color: var(--al-danger);
    font-weight: 600;
  }
}

/* 预警 */
.warning-section {
  background: rgba(255, 74, 74, 0.1);
  border: 1px solid rgba(255, 74, 74, 0.3);
  border-radius: 12px;
  padding: 14px;
}

.section-title {
  color: var(--al-text-secondary);
  font-size: 14px;
  margin-bottom: 10px;
  display: flex;
  align-items: center;
  gap: 8px;

  i {
    font-size: 14px;
  }
}

.warning-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.warning-item {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--al-danger);
  font-size: 13px;
  font-weight: 600;

  i {
    font-size: 12px;
  }
}

/* 收支 */
.section-card {
  background: var(--al-bg-card);
  border-radius: 12px;
  padding: 14px;
  border: 1px solid var(--al-border);
}

.ledger {
  font-size: 12px;
}

.ledger-group {
  margin-bottom: 6px;
}

.ledger-title {
  color: var(--al-text-secondary);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  margin-bottom: 4px;
}

.ledger-row {
  display: flex;
  justify-content: space-between;
  color: var(--al-text-body);
  padding: 3px 0;
}

.income-val {
  color: var(--al-success);
  font-weight: 600;
}

.expense-val {
  color: var(--al-warn);
  font-weight: 600;
}

.ledger-divider {
  height: 1px;
  background: var(--al-border);
  margin: 6px 0;
}

@media (max-width: 360px) {
  .resources-grid {
    grid-template-columns: 1fr;
  }
}
