
.panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.fleet-section {
  background: var(--al-bg-card);
  border-radius: 12px;
  padding: 14px;
  border: 1px solid var(--al-border);
}

.section-title {
  color: var(--al-text-secondary);
  font-size: 14px;
  margin-bottom: 10px;
  display: flex;
  align-items: center;
  gap: 8px;

  i {
    font-size: 14px;
  }
}

.fleet-count {
  margin-left: auto;
  font-size: 12px;
  color: var(--al-text-muted);
  font-weight: 400;
}

.fleet-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.fleet-card {
  background: var(--al-bg-item);
  border-radius: 10px;
  padding: 12px;
  border-left: 3px solid var(--al-accent);
  cursor: pointer;
  transition: all 0.25s;

  &:hover {
    background: var(--al-bg-hover);
  }

  &.sub {
    border-left-color: var(--al-success);
  }

  &.empty-slot {
    border-style: dashed;
    border-color: var(--al-border);
    border-left-width: 3px;
    cursor: default;
    opacity: 0.5;

    &:hover {
      background: var(--al-bg-item);
    }
  }
}

.fleet-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
}

.fleet-name {
  color: var(--al-text-body);
  font-size: 14px;
  font-weight: 600;
}

.fleet-oil {
  color: var(--al-warn);
  font-size: 12px;
  font-weight: 600;

  i {
    margin-right: 3px;
    font-size: 11px;
  }
}

.fleet-members {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.member-tag {
  background: rgba(74, 158, 255, 0.15);
  color: var(--al-text-muted);
  padding: 3px 8px;
  border-radius: 10px;
  font-size: 11px;

  &.sub {
    background: rgba(38, 208, 206, 0.15);
  }
}

/* 展开详情 */
.fleet-detail {
  margin-top: 10px;
  padding-top: 8px;
  border-top: 1px solid var(--al-border);
}

.detail-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 3px 0;
  font-size: 12px;
}

.detail-name {
  color: var(--al-text-body);
  flex: 1;
}

.detail-type {
  color: var(--al-text-muted);
  flex: 1;
  text-align: center;
}

.detail-oil {
  color: var(--al-warn);
  font-size: 11px;
  text-align: right;
  width: 60px;
}

.empty-content {
  text-align: center;
  color: var(--al-text-muted);
  font-size: 12px;
  padding: 8px;

  i {
    margin-right: 6px;
    font-size: 14px;
  }
}

/* 总耗油 */
.total-card {
  background: var(--al-bg-card);
  border-radius: 12px;
  padding: 14px 18px;
  border: 1px solid var(--al-border);
}

.total-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.total-label {
  color: var(--al-text-secondary);
  font-size: 14px;
}

.total-value {
  font-size: 22px;
  font-weight: 700;
  color: var(--al-text-primary);

  i {
    color: var(--al-warn);
    font-size: 16px;
    margin-right: 4px;
  }
}

.total-unit {
  font-size: 12px;
  font-weight: 400;
  color: var(--al-text-muted);
  margin-left: 4px;
}

/* 展开动画 */
.slide-enter-active,
.slide-leave-active {
  transition: all 0.25s ease;
  overflow: hidden;
}
.slide-enter-from,
.slide-leave-to {
  opacity: 0;
  max-height: 0;
}
.slide-enter-to,
.slide-leave-from {
  opacity: 1;
  max-height: 200px;
}
