
.panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.section-card {
  background: var(--al-bg-card);
  border-radius: 12px;
  padding: 14px;
  border: 1px solid var(--al-border);
}

.section-title {
  color: var(--al-text-secondary);
  font-size: 14px;
  margin-bottom: 10px;
  display: flex;
  align-items: center;
  gap: 8px;

  i {
    font-size: 14px;
  }
}

/* 待办事务 */
.todo-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.todo-item {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  background: var(--al-bg-item);
  border-radius: 8px;
  padding: 10px 12px;
  border-left: 3px solid var(--al-accent);
  cursor: pointer;
  transition: all 0.25s;

  &:hover {
    background: var(--al-bg-hover);
  }

  &.completed {
    opacity: 0.5;
    border-left-color: var(--al-success);

    .todo-name {
      text-decoration: line-through;
    }
  }

  &.warning {
    border-left-color: var(--al-warn);
  }
}

.todo-check {
  color: var(--al-accent);
  font-size: 16px;
  padding-top: 1px;
  flex-shrink: 0;
}

.todo-content {
  flex: 1;
  min-width: 0;
}

.todo-name {
  color: var(--al-text-body);
  font-size: 13px;
  margin-bottom: 4px;
}

.todo-cost {
  display: flex;
  gap: 12px;
  font-size: 11px;
  color: var(--al-text-muted);

  i {
    margin-right: 3px;
    font-size: 10px;
  }
}

.empty-state {
  text-align: center;
  padding: 16px;
  color: var(--al-text-muted);
  font-size: 13px;

  i {
    margin-right: 6px;
  }
}

/* 议会倒计时 */
.countdown-card {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.countdown-display {
  position: relative;
  width: 110px;
  height: 110px;
}

.countdown-svg {
  width: 100%;
  height: 100%;
}

.circle-bg {
  fill: none;
  stroke: var(--al-border);
  stroke-width: 6;
}

.circle-progress {
  fill: none;
  stroke: var(--al-accent);
  stroke-width: 6;
  stroke-linecap: round;
  transform: rotate(-90deg);
  transform-origin: 50% 50%;
  transition: stroke-dashoffset 0.5s ease;
}

.countdown-center {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  text-align: center;
}

.countdown-days {
  font-size: 28px;
  font-weight: 700;
  color: var(--al-text-secondary);
}

.countdown-label {
  font-size: 11px;
  color: var(--al-text-muted);
}

/* 人员名单 */
.lists-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.member-item {
  background: var(--al-bg-item);
  border-radius: 6px;
  padding: 8px 10px;
  margin-bottom: 6px;
  cursor: pointer;
  transition: all 0.2s;

  &:hover {
    background: var(--al-bg-hover);
    transform: translateY(-1px);
  }
}

.member-name {
  color: var(--al-text-body);
  font-size: 13px;
}

.member-detail {
  font-size: 11px;
  color: var(--al-text-muted);
  margin-top: 4px;
  padding-top: 4px;
  border-top: 1px solid var(--al-border);
}

/* 展开动画 */
.slide-enter-active,
.slide-leave-active {
  transition: all 0.2s ease;
  overflow: hidden;
}

.slide-enter-from,
.slide-leave-to {
  opacity: 0;
  max-height: 0;
}

.slide-enter-to,
.slide-leave-from {
  opacity: 1;
  max-height: 40px;
}

@media (max-width: 400px) {
  .lists-row {
    grid-template-columns: 1fr;
  }
}
